    private static void registerInstruction(String name, Supplier<? extends ScheduleInstruction> factory) {
        Schedule.INSTRUCTION_TYPES.add(Pair.of((Object)new ResourceLocation("createrailwaysnavigator", name), factory));
    }

    private static void registerCondition(String name, Supplier<? extends ScheduleWaitCondition> factory) {
        Schedule.CONDITION_TYPES.add(Pair.of((Object)new ResourceLocation("createrailwaysnavigator", name), factory));
    }

    public static void init() {
    }

    static {
        ModSchedule.registerInstruction("travel_section", TravelSectionInstruction::new);
        ModSchedule.registerInstruction("reset_timings", ResetTimingsInstruction::new);
        ModSchedule.registerInstruction("prioritized_destination_instruction", PrioritizedDestinationInstruction::new);
        ModSchedule.registerCondition("dynamic_delay", DynamicDelayCondition::new);
        ModSchedule.registerCondition("train_separation", TrainSeparationCondition::new);
    }
}

